create or replace function public.dreem_get_learner_onefile(p_student_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare s public.students%rowtype;v_role text;v_is_staff boolean:=false;v_is_guardian boolean:=false;v_receives_finance boolean:=false;v_is_student boolean:=false;v_result jsonb;
begin
 select * into s from public.students where id=p_student_id and merged_into_student_id is null;if not found then raise exception 'Learner not found';end if;
 select m.role into v_role from public.dreem_school_memberships m where m.school_id=s.school_id and m.profile_id=(select auth.uid()) and m.status='approved' limit 1;
 v_is_staff:=coalesce(v_role not in('parent','student'),false);v_is_student:=s.profile_id=(select auth.uid());
 select exists(select 1 from public.dreem_guardians g join public.dreem_student_guardians sg on sg.guardian_id=g.id and sg.school_id=g.school_id where g.user_id=(select auth.uid()) and sg.student_id=s.id and sg.school_id=s.school_id)into v_is_guardian;
 select exists(select 1 from public.dreem_guardians g join public.dreem_student_guardians sg on sg.guardian_id=g.id and sg.school_id=g.school_id where g.user_id=(select auth.uid()) and sg.student_id=s.id and sg.school_id=s.school_id and sg.receives_finance=true)into v_receives_finance;
 if not(v_is_staff or v_is_guardian or v_is_student)then raise exception 'Not authorized for this learner';end if;
 v_result:=jsonb_build_object('identity',jsonb_build_object('studentId',s.id,'matricule',s.matricule,'fullName',s.full_name,'className',s.class_name,'attendanceRate',s.attendance_rate,'riskLevel',case when v_is_staff then s.risk_level else null end,'dateOfBirth',s.date_of_birth,'sex',s.sex,'photoUrl',s.photo_url),'guardians',(select coalesce(jsonb_agg(jsonb_build_object('name',g.full_name,'relationship',sg.relationship,'isPrimary',sg.is_primary)),'[]'::jsonb)from public.dreem_student_guardians sg join public.dreem_guardians g on g.id=sg.guardian_id where sg.student_id=s.id and sg.school_id=s.school_id),'academics',jsonb_build_object('publishedReports',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'termId',r.term_id,'average',r.overall_average,'revision',r.revision,'publishedAt',r.published_at)order by r.published_at desc),'[]'::jsonb)from public.dreem_report_cards r where r.student_id=s.id and r.school_id=s.school_id and r.status='published'),'submissions',(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'assignmentId',a.assignment_id,'attempt',a.attempt,'status',a.status,'score',a.score,'feedback',a.feedback,'submittedAt',a.submitted_at)order by a.submitted_at desc),'[]'::jsonb)from public.dreem_assignment_submissions a where a.student_id=s.id and a.school_id=s.school_id)),'finance',case when v_is_staff or v_receives_finance then jsonb_build_object('account',(select to_jsonb(f)-'school_id' from public.fee_accounts f where f.student_id=s.id and f.school_id=s.school_id order by f.created_at desc limit 1),'charges',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'amount',c.amount,'waivedAmount',c.waived_amount,'status',c.status,'dueOn',c.due_on)order by c.due_on nulls last),'[]'::jsonb)from public.dreem_student_fee_charges c where c.student_id=s.id and c.school_id=s.school_id),'payments',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'receiptNumber',p.receipt_number,'method',p.method,'amount',p.amount,'receivedAt',p.received_at,'railCode',p.rail_code)order by p.received_at desc),'[]'::jsonb)from public.dreem_financial_payments p where p.student_id=s.id and p.school_id=s.school_id))else null end,'transport',jsonb_build_object('assignment',(select jsonb_build_object('id',t.id,'routeId',t.route_id,'pickupStopId',t.pickup_stop_id,'dropoffStopId',t.dropoff_stop_id,'status',t.status,'effectiveFrom',t.effective_from,'effectiveTo',t.effective_to)from public.dreem_transport_assignments t where t.student_id=s.id and t.school_id=s.school_id and t.status='active' order by t.created_at desc limit 1)),'credentials',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'cardNumber',c.card_number,'cardVersion',c.card_version,'status',c.status,'issuedAt',c.issued_at,'validUntil',c.valid_until)order by c.issued_at desc),'[]'::jsonb)from public.dreem_student_credentials c where c.student_id=s.id and c.school_id=s.school_id),'care',case when private.dreem_has_role(s.school_id,array['leadership','support'])then jsonb_build_object('openCaseCount',(select count(*)from public.dreem_student_cases c where c.student_id=s.id and c.school_id=s.school_id and c.status not in('resolved','closed','cancelled')),'urgentCaseCount',(select count(*)from public.dreem_student_cases c where c.student_id=s.id and c.school_id=s.school_id and c.status not in('resolved','closed','cancelled')and c.priority in('urgent','critical')))else null end,'readMeta',jsonb_build_object('schoolId',s.school_id,'viewerRole',v_role,'generatedAt',now()));
 insert into public.audit_events(school_id,actor_id,action,entity_type,entity_id,detail)values(s.school_id,(select auth.uid()),'learner.onefile_viewed','student',s.id,jsonb_build_object('role',v_role));return v_result;
end;$$;
revoke all on function public.dreem_get_learner_onefile(uuid) from public;grant execute on function public.dreem_get_learner_onefile(uuid) to authenticated;